/* Educational content is local, factual, and independent of medical reports. */
(function(root){
'use strict';
const facts=[
{id:'rice',pattern:/^(?:white |brown |steamed |cooked )?rice$/i,text:'Mmm, rice! Rice contains carbohydrates that your body can use for energy.',ingredient:'Rice is a source of carbohydrate.'},
{id:'apple',pattern:/^(?:an? |fresh |sliced )?apples?$/i,text:'Crunchy apple! Apples contain carbohydrates and fiber. The amount depends on the size and portion.',ingredient:'The apple contains carbohydrate and fiber.'},
{id:'bread',pattern:/^(?:whole.?wheat |white |whole.?grain )?(?:bread|toast)$/i,text:'Toast time! Bread contains carbohydrates that can give your body energy.',ingredient:'Bread is a source of carbohydrate.'},
{id:'pasta',pattern:/^(?:plain |cooked )?(?:pasta|spaghetti)$/i,text:'Pasta time! Pasta contains carbohydrates that your body can use for energy.',ingredient:'Pasta is a source of carbohydrate.'}
];
const fallback={id:'mixed',text:'That sounds yummy! Meals can contain several ingredients. A label, recipe, or trusted adult can help you learn about the carbs.',ingredient:'A meal may have several ingredients. Which ones contain carbohydrates?'};
const pictures=[
'<svg viewBox="0 0 160 90"><ellipse cx="80" cy="70" rx="60" ry="12" fill="#d3e1c8"/><path d="M29 48h102q-4 28-51 28T29 48" fill="#f4dca8" stroke="#748a63" stroke-width="3"/><circle cx="61" cy="42" r="13" fill="#e8ad78"/><circle cx="84" cy="38" r="16" fill="#a9c695"/><circle cx="105" cy="44" r="12" fill="#e8c875"/><path d="M38 48h84" stroke="#748a63" stroke-width="3"/></svg>',
'<svg viewBox="0 0 160 90"><circle cx="112" cy="45" r="31" fill="#d5e6c6" stroke="#748a63" stroke-width="3"/><circle cx="112" cy="45" r="14" fill="#f4e7be"/><circle cx="39" cy="43" r="14" fill="#e7c76e" stroke="#917b55" stroke-width="3"/><circle cx="39" cy="43" r="6" fill="#f5e9bd"/><path d="M52 43h37m-10-8 10 8-10 8" fill="none" stroke="#917b55" stroke-width="6" stroke-linecap="round"/></svg>',
'<svg viewBox="0 0 160 90"><path d="M80 75C58 61 34 47 38 28q3-17 20-17 15 0 22 14 7-14 22-14 17 0 20 17 4 19-42 47" fill="#e5aa94" stroke="#a57367" stroke-width="3"/><circle cx="80" cy="42" r="17" fill="#f9ead3"/><path d="M80 29v26M67 42h26" stroke="#748a63" stroke-width="5" stroke-linecap="round"/></svg>'
];
const steps=[
{icon:'🍽️',label:'FOOD',text:'Food gives our bodies energy. Many foods contain carbohydrates, which break down into glucose.'},
{icon:'🔑',label:'INSULIN',text:'Insulin helps glucose move into cells so our bodies can use that energy.'},
{icon:'💛',label:'YOUR PLAN',text:'With type 1 diabetes, the body makes little or no insulin. Mealtime insulin follows your own diabetes care plan. Your trusted adult can help.'}
];
function classify(name){const v=String(name||'').trim().replace(/\s+/g,' ');return facts.find(f=>f.pattern.test(v))||fallback}
function blank(){return {storySeen:false,storySteps:[],foodCards:[]}}
function normalize(value){const p=value&&typeof value==='object'?value:{};return {storySeen:!!p.storySeen,storySteps:Array.isArray(p.storySteps)?[...new Set(p.storySteps.filter(n=>Number.isInteger(n)&&n>=0&&n<3))]:[],foodCards:Array.isArray(p.foodCards)?[...new Set(p.foodCards.filter(x=>typeof x==='string'))]:[]}}
function addUnique(list,id){return list.includes(id)?list:[...list,id]}
const core={classify,blank,normalize,addUnique,steps};if(typeof module!=='undefined'&&module.exports)module.exports=core;if(!root.document)return;
const key='diabuddy-learning-v1';let progress;try{progress=normalize(JSON.parse(localStorage.getItem(key)||'{}'))}catch{progress=blank()}
function persist(){try{localStorage.setItem(key,JSON.stringify(progress))}catch{}}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function showStory(){let index=0;progress.storySeen=true;persist();function draw(){const step=steps[index];progress.storySteps=addUnique(progress.storySteps,index);persist();const dialog=document.querySelector('#modal'),container=document.querySelector('#modal-content');container.innerHTML=`<div class="eyebrow">A LITTLE STORY · ${index+1} OF 3</div><h2>How Buddy uses food</h2><div class="learning-illustration" aria-hidden="true">${pictures[index]}<small>${step.label}</small></div><p class="learning-story-text">${escape(step.text)}</p><p class="helper">A story to explore with a trusted adult. Feeding Buddy does not record, deliver, or verify insulin.</p><div class="modal-actions"><button class="secondary" id="learn-skip">Skip story</button>${index?'<button class="secondary" id="learn-back">Back</button>':''}<button class="primary" id="learn-next">${index===2?'Done':'Next →'}</button></div>`;if(!dialog.open)dialog.showModal();document.querySelector('#learn-skip').onclick=()=>dialog.close();if(index)document.querySelector('#learn-back').onclick=()=>{index--;draw()};document.querySelector('#learn-next').onclick=()=>{if(index===2)dialog.close();else{index++;draw()}}}draw()}
const lessons=[
{id:'type-1-basics',label:'WEEK 1',title:'What is type 1 diabetes?',steps:[
{title:'Hi, friend!',text:'I have type 1 diabetes. Want to learn what that means with me? We can take it one little step at a time.'},
{title:'Energy for our bodies',text:'Our bodies need energy to play, learn, and grow. Glucose (say: GLOO-kose) is a kind of sugar that travels in our blood and gives our bodies energy.'},
{title:'Meet insulin',text:'Insulin is a helper made by a part of the body called the pancreas. It helps glucose move from the blood into the body’s cells, where it can be used for energy.'},
{title:'My type 1 diabetes',text:'With type 1 diabetes, my body makes little or no insulin. That means I need insulin to help my body use glucose. Diabetes is nobody’s fault, and we are not alone!'}]},
{id:'school-conversation',label:'WEEK 2',title:'Talking about diabetes at school',steps:[
{title:'Let’s practice together',text:'Sometimes I want a teacher or school nurse to know about my type 1 diabetes. I can ask a trusted adult to practice with me first.'},
{title:'Starting the conversation',text:'I could say: “Hi! I have type 1 diabetes. My body needs help with insulin and keeping track of my blood sugar.”'},
{title:'Asking for support',text:'I could say: “Sometimes I might need to take a break, check my blood sugar, or visit the nurse. Can we talk about my school plan?”'},
{title:'You have a team',text:'It’s okay to ask questions or say, “Can you help me tell my teacher?” My family and school team can help explain the plan that is right for me.'}]}];
function lessonSummary(completed=[]){return {completed:lessons.filter(l=>Array.isArray(completed)&&completed.includes(l.id)).length,total:lessons.length}}
function homeCard(name,completed=[]){const summary=lessonSummary(completed);return `<details class="bunny-intro"><summary><svg class="learning-book" viewBox="0 0 24 24" aria-hidden="true" shape-rendering="crispEdges"><path fill="currentColor" d="M2 4h7l3 3 3-3h7v15h-7l-3 3-3-3H2zm2 2v11h5l2 2V8L8 6zm9 2v11l2-2h5V6h-4z"/></svg><span class="learning-summary-copy"><strong>Learn a little with ${escape(name)}</strong><small id="lesson-summary-progress">${summary.completed} of ${summary.total} lessons complete · Optional stories</small></span></summary><div class="bunny-intro-content"><div class="learning-welcome"><span class="eyebrow">A LITTLE DISCOVERY, TOGETHER</span><h2>Little lessons. Room to wonder.</h2><p>Explore with ${escape(name)} and a trusted adult, one story at a time.</p></div><button class="primary" id="diabetes-start">Choose a lesson →</button><div id="diabetes-lesson" aria-live="polite"></div><p class="learning-note">Illustrated learning, not treatment instructions. Follow your own care plan and ask your care team for guidance.</p></div></details>`}
function showDiabetesLesson(container,rewardLesson,options={}){
 let lesson=null,index=0;const completed=()=>typeof options.completed==='function'?options.completed():[];
 function updateSummary(){const s=lessonSummary(completed()),el=document.querySelector('#lesson-summary-progress');if(el)el.textContent=s.completed+' of '+s.total+' lessons complete · Optional stories';}
 function draw(){
  if(lesson===null){container.innerHTML=`<div class="diabetes-lesson"><div class="lesson-progress">YOUR LITTLE LIBRARY</div><h3 tabindex="-1">What shall we discover?</h3><div class="lesson-list">${lessons.map((item,i)=>{const done=completed().includes(item.id);return `<button class="lesson-choice" data-lesson="${i}"><span class="lesson-number" aria-hidden="true">0${i+1}</span><span class="lesson-choice-copy"><small>${item.label}</small><strong>${escape(item.title)}</strong><span class="lesson-state">${done?'Complete · Read again':'Start story · 5 coins once'}</span></span><b aria-hidden="true">→</b></button>`}).join('')}</div></div>`;container.querySelectorAll('[data-lesson]').forEach(button=>button.onclick=()=>{lesson=Number(button.dataset.lesson);index=0;draw()});return;}
  const selected=lessons[lesson],step=selected.steps[index];container.innerHTML=`<div class="diabetes-lesson"><div class="lesson-progress-row"><span class="lesson-progress">${selected.label} · ${index+1} OF ${selected.steps.length}</span><progress class="lesson-meter" value="${index+1}" max="${selected.steps.length}" aria-label="Lesson steps viewed"></progress></div><div class="lesson-heading"><h3 tabindex="-1">${escape(step.title)}</h3></div><p class="lesson-speech">${escape(step.text)}</p><div class="lesson-actions"><button class="secondary" id="diabetes-back">← ${index?'Back':'Lessons'}</button><button class="primary" id="diabetes-next">${index===selected.steps.length-1?'Finish story':'Next →'}</button></div></div>`;
  container.querySelector('#diabetes-back').onclick=()=>{if(index)index--;else lesson=null;draw()};
  container.querySelector('#diabetes-next').onclick=()=>{if(index===selected.steps.length-1){const earned=rewardLesson(selected.id);updateSummary();container.innerHTML=`<div class="diabetes-lesson lesson-complete"><span class="lesson-complete-mark" aria-hidden="true">✓</span><div class="lesson-progress">STORY COMPLETE</div><h3 tabindex="-1">Wonderful learning!</h3><p>${earned?'You earned 5 coins for your bank.':'This story is already in your collection. Revisit it whenever you like.'}</p><div class="lesson-actions"><button class="primary" id="diabetes-lessons">Choose another lesson →</button></div></div>`;container.querySelector('#diabetes-lessons').onclick=()=>{lesson=null;draw()};}else{index++;draw();container.querySelector('h3')?.focus?.({preventScroll:true});}};
 }
 draw();
}
function afterMeal(){if(!progress.storySeen)showStory()}
function updateFood(value){const container=document.querySelector('#food-learning');if(!container)return;const name=String(value||'').trim();if(!name){container.innerHTML='';return}const info=classify(name);container.innerHTML=`<section class="food-fact"><div class="eyebrow">CARB DETECTIVE · A LITTLE FACT</div><p>${escape(info.text)}</p><button type="button" class="text-link" id="explore-food" aria-expanded="false">Explore this food ↗</button><div id="explore-food-detail" hidden></div></section>`;container.querySelector('#explore-food').onclick=e=>{const detail=container.querySelector('#explore-food-detail');const open=detail.hidden;detail.hidden=!open;e.currentTarget.setAttribute('aria-expanded',String(open));if(open){progress.foodCards=addUnique(progress.foodCards,info.id);persist();detail.innerHTML=`<div class="food-explore"><p><strong>What ingredients might contain carbohydrates?</strong><br>${escape(info.ingredient)}</p><p><strong>Where could we find more information?</strong><br>Try a food label, recipe, or ask a trusted adult.</p><p><strong>What portion are we looking at?</strong><br>Compare the portion with the label or recipe serving size. A name or picture alone can’t tell us the amount.</p></div>`}}}
function parentCard(){return `<section class="card card-pad learning-parent"><div class="eyebrow">LEARNING TOGETHER</div><h2>${escape(typeof buddyName==='function'?buddyName():'Your buddy')}’s learning</h2><p>${progress.storySteps.length} of 3 story steps viewed · ${progress.foodCards.length} food ${progress.foodCards.length===1?'card':'cards'} explored</p><p class="helper">Participation only. It does not show food amounts, glucose, insulin, or treatment completion. Stored in this browser.</p><p><strong>Content awaiting clinician review.</strong> Explore with your child and follow their care plan.</p><details><summary>Sources for parents</summary><ul><li><a href="https://www.cdc.gov/diabetes/healthy-eating/carb-counting-manage-blood-sugar.html" target="_blank" rel="noopener noreferrer">CDC: carbohydrates and portions</a></li><li><a href="https://www.niddk.nih.gov/health-information/diabetes/overview/what-is-diabetes/type-1-diabetes" target="_blank" rel="noopener noreferrer">NIDDK: type 1 diabetes and insulin</a></li><li><a href="https://diabetes.org/food-nutrition/reading-food-labels/making-sense-food-labels" target="_blank" rel="noopener noreferrer">American Diabetes Association: food labels</a></li></ul></details></section>`}
root.DiaLearning={lessonSummary,homeCard,showDiabetesLesson,storySeen:()=>progress.storySeen,showStory,afterMeal,updateFood,parentCard};
})(typeof window==='undefined'?globalThis:window);
